(()=>{'use strict';
if(window.__CCNER_CLINICAL_REPORT_FILE__)return;window.__CCNER_CLINICAL_REPORT_FILE__=true;
function wire(){const area=document.querySelector('#ciText');if(!area||document.querySelector('#ciFile'))return false;const wrap=document.createElement('label');wrap.className='ci-label';wrap.innerHTML='Load a text report file <input id="ciFile" class="ci-input" type="file" accept=".txt,.md,.json,.csv,text/plain,application/json,text/csv"><small style="display:block;margin-top:5px;color:#6d746e;font-weight:400">For PDF/DOCX, paste the report text here. The browser build does not upload the original document.</small>';area.parentNode.insertBefore(wrap,area);const input=wrap.querySelector('input');input.onchange=async()=>{const f=input.files?.[0];if(!f)return;try{const text=await f.text();area.value=text.slice(0,30000);const title=document.querySelector('#ciTitle');if(title&&!title.value)title.value=f.name.replace(/\.[^.]+$/,'')}catch(_){}};return true}let n=0;const t=setInterval(()=>{n++;if(wire()||n>60)clearInterval(t)},300);wire();
})();
